33	    // 保守：仅 1 视为在售；其它数字留给观测日志，默认不当作在售
34	    if (s4 === 1) return true;
35	    if (s4 === 2 || s4 === 3 || s4 === 4 || s4 === 5 || s4 === 6) return false;
36	  }
37	
38	  // 若调用方用 ACTIVE 筛选拉回，列表内默认都算在售
