57	export function normalizeGoods(g, { assumedActive = false } = {}) {
58	  const id = goodsIdOf(g);
59	  if (!id) return null;
60	  const row = assumedActive ? { ...g, __assumedActive: true } : g;
61	  return {
62	    goodsId: id,
63	    name: nameOf(g),
64	    active: isActiveGoods(row),
65	    lowTraffic: isLowTraffic(g),
