67	    status4VO: g?.status4VO ?? null,
68	    subStatus4VO: g?.subStatus4VO ?? null,
69	    goodsShowSubStatus: g?.goodsShowSubStatus ?? null,
70	    goodsStatus: g?.goodsStatus ?? null,
71	    outGoodsSn: g?.outGoodsSn || '',
72	    thumbUrl: g?.thumbUrl || '',
