76	/**
77	 * 分页拉全量（list.query）
78	 * goodsSearchType: 1=Available/off the shelf, 4=unpublished, 5=draft, 6=deleted
79	 */
80	export async function fetchAllListQuery(client, accessToken, {
81	  goodsSearchType = 1,
82	  goodsStatusFilterType,
83	  goodsSearchTags,
84	  pageSize = PAGE_SIZE_MAX,
85	  assumedActive = false,
86	} = {}) {
87	  const size = Math.min(PAGE_SIZE_MAX, Math.max(1, Number(pageSize) || PAGE_SIZE_MAX));
88	  const all = [];
89	  let pageNo = 1;
90	  let total = null;
91	  for (;;) {
92	    const biz = {
93	      pageNo,
94	      pageSize: size,
95	      goodsSearchType,
96	    };
97	    if (goodsStatusFilterType != null) biz.goodsStatusFilterType = goodsStatusFilterType;
98	    if (Array.isArray(goodsSearchTags) && goodsSearchTags.length) biz.goodsSearchTags = goodsSearchTags;
99	
100	    const data = await client.call('bg.local.goods.list.query', biz, { accessToken });
101	    const result = data.result || {};
102	    const list = result.goodsList || result.data || [];
103	    if (typeof result.total === 'number') total = result.total;
104	    for (const g of list) {
105	      const n = normalizeGoods(g, { assumedActive });
106	      if (n) all.push(n);
107	    }
108	    if (!list.length) break;
109	    if (total != null && all.length >= total) break;
110	    if (list.length < size) break;
111	    pageNo += 1;
112	    if (pageNo > 500) throw new Error('list.query 分页超过 500 页，中止防死循环');
113	  }
114	  return { items: all, total: total ?? all.length };
115	}
