118	 * 分页拉全量（list.retrieve）
119	 * goodsSearchType: ALL | ACTIVE | INACTIVE | INCOMPLETE | DRAFT | DELETED
120	 */
121	export async function fetchAllListRetrieve(client, accessToken, {
122	  goodsSearchType = 'ACTIVE',
123	  goodsSearchTags,
124	  pageSize = PAGE_SIZE_MAX,
125	} = {}) {
126	  const size = Math.min(PAGE_SIZE_MAX, Math.max(1, Number(pageSize) || PAGE_SIZE_MAX));
127	  const all = [];
128	  let pageToken = undefined;
129	  let total = null;
130	  let guard = 0;
131	  const assumedActive = String(goodsSearchType).toUpperCase() === 'ACTIVE';
132	  for (;;) {
133	    const biz = {
134	      goodsSearchType,
135	      pageSize: size,
136	    };
137	    if (pageToken) biz.pageToken = pageToken;
138	    if (Array.isArray(goodsSearchTags) && goodsSearchTags.length) biz.goodsSearchTags = goodsSearchTags;
139	
