1	/**
2	 * Temu 跨境父体全量拉取（30 天滑窗 + 分页 + 去重）
3	 */
4	import { ymd } from './client.js';
5	import { log } from '../logger.js';
6	
7	/** Temu 生命周期：12=已加入站点(在售) 13=已下架 */
8	export const SELECT_STATUS = {
9	  ON_SALE: '12',
10	  DELISTED: '13',
11	};
12	
13	function parseYmd(s) {
14	  const [y, m, d] = s.split('-').map(Number);
15	  return new Date(y, m - 1, d);
16	}
17	
18	function fmtYmd(d) {
19	  return ymd(d);
20	}
21	
22	/** 倒序 30 天窗口 */
23	export function* iterWindows(startDate, endDate, maxSpanDays = 30) {
24	  let end = parseYmd(endDate);
25	  let start = parseYmd(startDate);
26	  if (start > end) [start, end] = [end, start];
27	  let curEnd = end;
28	  while (curEnd >= start) {
29	    const curStart = new Date(curEnd);
30	    curStart.setDate(curStart.getDate() - (maxSpanDays - 1));
31	    if (curStart < start) curStart.setTime(start.getTime());
32	    yield { startDate: fmtYmd(curStart), endDate: fmtYmd(curEnd) };
33	    curEnd = new Date(curStart);
34	    curEnd.setDate(curEnd.getDate() - 1);
35	  }
36	}
37	
38	/**
39	 * @param {ReturnType<import('./client.js').createSellfoxClient>} client
40	 * @param {{ shopIds: string[], pageSize?: number, maxPagesPerWindow?: number, dateType?: string, startDate?: string, endDate?: string, lookbackDays?: number }} opts
41	 */
42	export async function fetchAllCrossParents(client, opts) {
43	  const pageSize = Math.min(100, Number(opts.pageSize) || 100);
44	  const maxPages = Number(opts.maxPagesPerWindow) || 50;
45	  const dateType = opts.dateType || 'updateDate';
46	  const endDate = opts.endDate || fmtYmd(new Date());
47	  let startDate = opts.startDate;
48	  if (!startDate) {
49	    const d = parseYmd(endDate);
50	    d.setDate(d.getDate() - (Number(opts.lookbackDays) || 30));
51	    startDate = fmtYmd(d);
52	  }
53	
54	  const all = [];
55	  const seen = new Set();
56	  const windowsMeta = [];
57	
58	  for (const w of iterWindows(startDate, endDate, 30)) {
59	    let pageNo = 1;
60	    let totalSize = null;
61	    let totalPage = null;
62	    let windowRows = 0;
63	    while (pageNo <= maxPages) {
64	      const data = await client.temuCrossParentPage({
65	        pageNo,
66	        pageSize,
67	        shopIds: opts.shopIds,
68	        dateType,
69	        startDate: w.startDate,
