1	/**
2	 * OpenAPI 一轮监测：拉目录 → diff → 飞书 → 写快照
3	 */
4	import { readFileSync, writeFileSync, mkdirSync, existsSync } from 'node:fs';
5	import { dirname } from 'node:path';
6	import { createOpenApiClient } from './client.js';
7	import { fetchStoreCatalog } from './goods.js';
8	import { diffCatalog, formatAlertLines } from './diff.js';
9	import { sendFeishu } from '../feishu.js';
10	import { log } from '../logger.js';
11	
12	function loadState(path) {
13	  try {
14	    if (!existsSync(path)) return { stores: {} };
15	    return JSON.parse(readFileSync(path, 'utf8'));
16	  } catch {
17	    return { stores: {} };
18	  }
19	}
20	
21	function saveState(path, state) {
22	  mkdirSync(dirname(path), { recursive: true });
23	  writeFileSync(path, JSON.stringify(state, null, 2), 'utf8');
24	}
25	
26	/**
27	 * @param {object} cfg loadOpenApiConfig() 结果
28	 * @param {{ dryRun?: boolean }} [opts]
29	 */
30	export async function runOpenApiOnce(cfg, opts = {}) {
31	  const enabledStores = (cfg.stores || []).filter((s) => s.enabled !== false && s.accessToken);
32	  if (!cfg.appKey || !cfg.appSecret) throw new Error('缺少 appKey/appSecret');
33	  if (!enabledStores.length) throw new Error('没有可监测的店铺（需 name + accessToken）');
34	
35	  const state = loadState(cfg.stateFile);
36	  if (!state.stores) state.stores = {};
37	
38	  const summary = [];
39	
40	  for (const store of enabledStores) {
41	    const name = store.name;
42	    const baseUrl = (store.baseUrl || cfg.baseUrl).replace(/\/openapi\/router\/?$/i, '').replace(/\/$/, '');
43	    const client = createOpenApiClient({
44	      appKey: cfg.appKey,
45	      appSecret: cfg.appSecret,
46	      baseUrl,
47	      debug: cfg.debug,
48	    });
49	
50	    log.info(`OpenAPI 监测店铺：${name}`);
51	    let catalog;
52	    try {
53	      catalog = await fetchStoreCatalog(client, store.accessToken, {
54	        apiMode: cfg.apiMode,
55	        pageSize: cfg.pageSize,
56	        forceAssumeActiveOnType1: cfg.forceAssumeActiveOnType1,
57	      });
58	    } catch (e) {
59	      if (e.partial) {
60	        log.warn(`${name} 标签筛选失败，已用 ACTIVE 字段回退：`, e.message);
61	        catalog = {
62	          activeMap: Object.fromEntries((e.partial.activeItems || []).map((x) => [x.goodsId, { name: x.name }])),
63	          lowTrafficMap: Object.fromEntries((e.partial.lowItems || []).map((x) => [x.goodsId, { name: x.name }])),
64	          restrictedMap: Object.fromEntries((e.partial.restrictedItems || []).map((x) => [x.goodsId, { name: x.name }])),
65	          counts: {
66	            active: e.partial.activeItems?.length || 0,
67	            lowTraffic: e.partial.lowItems?.length || 0,
68	            restricted: e.partial.restrictedItems?.length || 0,
69	          },
70	        };
71	      } else {
72	        log.error(`${name} 拉取失败：`, e.message);
73	        summary.push({ store: name, ok: false, error: e.message });
74	        continue;
75	      }
76	    }
77	
78	    log.info(
79	      `${name} 目录：在售=${catalog.counts.active} 低流量=${catalog.counts.lowTraffic} 限流=${catalog.counts.restricted}`,
80	    );
81	    if (cfg.debug && catalog.rawSample?.length) {
82	      log.info(`${name} 样本：`, catalog.rawSample);
83	    }
84	
85	    const prev = state.stores[name]?.snapshot || null;
86	    const { events, nextSnap, isFirst, skipDelistUpdate } = diffCatalog(prev, catalog, cfg.alerts);
87	
88	    if (isFirst) {
89	      log.info(`${name} 首轮：建立基准，不告警（在售 ${catalog.counts.active}）`);
90	    } else if (skipDelistUpdate) {
91	      log.warn(`${name} 跳过下架更新（扫描疑似不全）`);
92	    }
93	
94	    const alertEvents = events.filter((e) => e.severity === 'alert');
95	    if (alertEvents.length && !opts.dryRun) {
96	      const lines = formatAlertLines(name, alertEvents, { editBaseUrl: cfg.editBaseUrl });
97	      const title = '🔔 Temu OpenAPI 监测告警';
98	      await sendFeishu(
99	        { feishuWebhooks: cfg.feishuWebhooks, feishuSecret: cfg.feishuSecret },
100	        { title, template: 'red', lines },
101	      );
102	      log.info(`${name} 已告警 ${alertEvents.length} 类事件`);
103	    } else if (alertEvents.length && opts.dryRun) {
104	      log.info(`${name} dryRun 告警内容：`, formatAlertLines(name, alertEvents, { editBaseUrl: cfg.editBaseUrl }));
105	    } else if (!isFirst) {
106	      log.info(`${name} 本轮无异常`);
107	    }
108	
109	    state.stores[name] = {
110	      latest: {
111	        ...catalog.counts,
112	        ts: Date.now(),
113	      },
114	      snapshot: nextSnap,
115	    };
116	    summary.push({
117	      store: name,
118	      ok: true,
119	      counts: catalog.counts,
120	      events: events.map((e) => e.type),
121	      isFirst,
122	    });
123	  }
124	
125	  if (!opts.dryRun) saveState(cfg.stateFile, state);
126	  return summary;
127	}
128	
129	/** 探测：token 权限 + 拉 1 页商品 */
130	export async function probeStore(cfg, storeName) {
131	  const store = (cfg.stores || []).find((s) => s.name === storeName) || (cfg.stores || [])[0];
132	  if (!store?.accessToken) throw new Error('未找到店铺 accessToken');
133	  const baseUrl = (store.baseUrl || cfg.baseUrl).replace(/\/openapi\/router\/?$/i, '').replace(/\/$/, '');
134	  const client = createOpenApiClient({
135	    appKey: cfg.appKey,
136	    appSecret: cfg.appSecret,
137	    baseUrl,
138	    debug: true,
139	  });
140	
141	  let info = null;
142	  try {
143	    info = await client.tokenInfo(store.accessToken);
144	  } catch (e) {
145	    log.warn('tokenInfo 失败（可忽略）：', e.message);
146	  }
147	
148	  let page = null;
149	  try {
150	    page = await client.call(
151	      'bg.local.goods.list.query',
152	      { pageNo: 1, pageSize: 5, goodsSearchType: 1, goodsStatusFilterType: 1 },
153	      { accessToken: store.accessToken },
154	    );
155	  } catch (e) {
156	    // 再试 retrieve
157	    try {
158	      page = await client.call(
159	        'temu.local.goods.list.retrieve',
160	        { goodsSearchType: 'ACTIVE', pageSize: 5 },
161	        { accessToken: store.accessToken },
162	      );
163	    } catch (e2) {
164	      return { store: store.name, info, listError: e.message, retrieveError: e2.message };
165	    }
166	  }
167	
168	  const result = page?.result || {};
169	  const list = result.goodsList || [];
170	  return {
171	    store: store.name,
172	    mallId: info?.result?.mallId,
173	    apiScopeList: info?.result?.apiScopeList || info?.result?.api_scope_list,
174	    sampleCount: list.length,
175	    total: result.total,
176	    sample: list.slice(0, 3).map((g) => ({
177	      goodsId: g.goodsId,
178	      goodsName: g.goodsName,
179	      status4VO: g.status4VO,
180	      lowTrafficTag: g.lowTrafficTag,
181	      restrictedTrafficTag: g.restrictedTrafficTag,
182	      goodsStatus: g.goodsStatus,
183	    })),
184	  };
185	}
