# Does sellfox getChildInfo return more fields? Search docs/logs
import os
root=r'E:/project/海外仓/sellfox-bridge'
for dirpath,dirs,files in os.walk(root):
  if 'pycache' in dirpath: continue
  for f in files:
    if f.endswith(('.md','.py','.json','.log','.txt')):
      p=os.path.join(dirpath,f)
      try: t=open(p,encoding='utf-8',errors='ignore').read()
      except: continue
      if 'getChildInfo' in t or 'ChildInfo' in t or 'extCode' in t:
        if 'getChildInfo' in t or ('extCode' in t and 'temu' in t.lower()):
          print(p.replace(root,''), 'getChild', t.count('getChildInfo'), 'extCode', t.count('extCode'))
"

